export type Cell = [number, number];

const MIN_LIVE_NEIGHBORS_FOR_SURVIVAL = 2;
const MAX_LIVE_NEIGHBORS_FOR_SURVIVAL = 3;

export function nextGeneration(cells: Cell[]): Cell[] {
  return cells.filter((cell) => survives(cell, cells));
}

function survives(cell: Cell, livingCells: Cell[]): boolean {
  const liveNeighbors = countLiveNeighbors(cell, livingCells);
  return (
    liveNeighbors >= MIN_LIVE_NEIGHBORS_FOR_SURVIVAL &&
    liveNeighbors <= MAX_LIVE_NEIGHBORS_FOR_SURVIVAL
  );
}

function countLiveNeighbors(cell: Cell, livingCells: Cell[]): number {
  return livingCells.filter((other) => isNeighbor(cell, other)).length;
}

function isNeighbor([x, y]: Cell, [otherX, otherY]: Cell): boolean {
  const sameCell = x === otherX && y === otherY;
  return !sameCell && Math.abs(x - otherX) <= 1 && Math.abs(y - otherY) <= 1;
}
